// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0) && caddress != address(0x00000000000000000000000000000000DeaDBeef));
        // Deploy a minimal mock that always returns success
        address mock = address(new MockERC20());
        vm.assume(caddress != address(c) && caddress != mock);

        bool success;
        (success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
        assertTrue(success);
    }
}

contract MockERC20 {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

